import re
xml=open('ex/xl/worksheets/sheet1.xml', encoding='utf-8').read()
# parse cells per row with style and value type
rows = {}
for m in re.finditer(r'<row r="(\d+)"([^>]*)>(.*?)</row>', xml, re.DOTALL):
    r = int(m.group(1)); attr=m.group(2); body=m.group(3)
    rows[r]={'attr':attr, 'cells':{}}
    for cm in re.finditer(r'<c r="([A-Z]+\d+)"([^>]*?)(?:/>|>(.*?)</c>)', body, re.DOTALL):
        coord, cattrs, content = cm.groups()
        s = re.search(r's="(\d+)"', cattrs)
        t = re.search(r't="(\w+)"', cattrs)
        v = None
        vm = re.search(r'<v>(.*?)</v>', content, re.DOTALL)
        if vm: v = vm.group(1)
        ism = re.search(r'<is>.*?<t[^>]*>(.*?)</t>', content, re.DOTALL)
        if ism: v = ism.group(1)
        rows[r]['cells'][coord] = (s.group(1) if s else None, t.group(1) if t else None, v)
for r in range(1, 29):
    if r in rows:
        cells = rows[r]['cells']
        out=[]
        for c in 'ABCDEFGHIJKLMNOPQRSTUV':
            coord = f'{c}{r}'
            if coord in cells:
                s,t,v = cells[coord]
                out.append(f'{c}:s{s}/{v}')
            else:
                out.append(f'{c}:-')
        print(r, ' | '.join(out))
