import re, difflib
def norm(s):
    return re.sub(r'>\s+<', '><', s).strip()
g = norm(open('/tmp/gld/xl/worksheets/sheet1.xml', encoding='utf-8').read())
f = norm(open('fld/xl/worksheets/sheet1.xml', encoding='utf-8').read())
# tokenize by tags
def tokens(s):
    return re.findall(r'<[^>]*>|[^<]+', s)
gt = tokens(g); ft = tokens(f)
sm = difflib.SequenceMatcher(a=gt, b=ft, autojunk=False)
for tag, i1, i2, j1, j2 in sm.get_opcodes():
    if tag != 'equal':
        print(tag, 'g:', ''.join(gt[i1:i2])[:300])
        print(tag, 'f:', ''.join(ft[j1:j2])[:300])
        print('---')
